with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , SUSPFRAUDREASON as FRAUD_SUSPICION_REASON
        , 'BJAZ_HM_HOSP_MASTER_EXTN1' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hosp_master_extn1') }}
    where (nullif(trim(HOSID),'')) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then FRAUD_SUSPICION_REASON end) as FRAUD_SUSPICION_REASON,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK
),

hashed as (
    select
        *,
        case when FRAUD_SUSPICION_REASON is not null
                     then md5(upper(coalesce(cast(FRAUD_SUSPICION_REASON as varchar), '')))
                end as SAT_PARTY_FRAUD_PROFILE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_PARTY_FRAUD_PROFILE_HASHDIFF is not null
